type DealStage = "intake" | "diligence" | "draft" | "internal_review" | "client_review" | "signed" | "archived";
type TransactionType = "venda" | "locacao" | "outro";

const stageMeta: Record<DealStage, { label: string; className: string }> = {
  intake: { label: "Dados do negócio", className: "bg-slate-100 text-slate-700 border-slate-200" },
  diligence: { label: "Diligência", className: "bg-amber-50 text-amber-800 border-amber-200" },
  draft: { label: "Minuta", className: "bg-violet-50 text-violet-800 border-violet-200" },
  internal_review: { label: "Revisão interna", className: "bg-sky-50 text-sky-800 border-sky-200" },
  client_review: { label: "Revisão do cliente", className: "bg-blue-50 text-blue-800 border-blue-200" },
  signed: { label: "Assinado", className: "bg-emerald-50 text-emerald-800 border-emerald-200" },
  archived: { label: "Arquivado", className: "bg-zinc-100 text-zinc-700 border-zinc-200" },
};

function StageBadge({ stage }: { stage: DealStage }) {
  const meta = stageMeta[stage];
  return <Badge variant="outline" className={`rounded-md border px-2 py-0.5 text-[11px] font-semibold ${meta.className}`}>{meta.label}</Badge>;
}

function formatMoney(value?: number | null) {
  if (value === null || value === undefined) return "Não informado";
  return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL", maximumFractionDigits: 0 }).format(value);
}

function formatDate(value?: string | Date | null) {
  if (!value) return "Sem prazo";
  return new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(value));
}

function dateInputValue(value?: string | Date | null) {
  if (!value) return "";
  return new Date(value).toISOString().slice(0, 10);
}

function shareUrl(path: string) {
  return `${window.location.origin}${path}`;
}

async function copyShareLink(path: string, label: string) {
  try {
    await navigator.clipboard.writeText(shareUrl(path));
    toast.success(`${label} copiado para a área de transferência.`);
  } catch {
    toast.error("Não foi possível copiar o link. Tente novamente.");
  }
}

function PageHeader({ eyebrow, title, description, actions }: { eyebrow?: string; title: string; description: string; actions?: React.ReactNode }) {
  return (
    <div className="mb-8 flex flex-col gap-5 border-b border-border/80 pb-7 lg:flex-row lg:items-end lg:justify-between">
      <div className="max-w-3xl">
        {eyebrow ? <p className="mb-2 text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground">{eyebrow}</p> : null}
        <h1 className="font-display text-3xl font-semibold tracking-[-0.035em] text-foreground md:text-4xl">{title}</h1>
        <p className="mt-2 text-sm leading-6 text-muted-foreground">{description}</p>
      </div>
      {actions ? <div className="flex shrink-0 flex-wrap gap-2">{actions}</div> : null}
    </div>
  );
}

function EmptyState({ icon: Icon, title, description, action }: { icon: typeof FileText; title: string; description: string; action?: React.ReactNode }) {
  return (
    <div className="flex min-h-60 flex-col items-center justify-center rounded-xl border border-dashed border-border bg-card px-6 py-10 text-center">
      <div className="flex size-11 items-center justify-center rounded-xl bg-muted text-muted-foreground"><Icon className="size-5" /></div>
      <h3 className="mt-4 font-display text-lg font-semibold tracking-tight">{title}</h3>
      <p className="mt-1 max-w-md text-sm leading-6 text-muted-foreground">{description}</p>
      {action ? <div className="mt-5">{action}</div> : null}
    </div>
  );
}

function MetricCard({ icon: Icon, label, value, helper, accent = "bg-zinc-400" }: { icon: typeof FileText; label: string; value: string | number; helper: string; accent?: string }) {
  return (
    <Card className="relative overflow-hidden border-border/80 bg-card shadow-[0_1px_2px_rgba(15,23,42,0.03)]">
      <span className={`absolute right-5 top-5 size-2 rounded-full ${accent}`} />
      <CardHeader className="pb-2"><div className="flex items-center gap-2 text-xs font-medium text-muted-foreground"><Icon className="size-3.5" />{label}</div></CardHeader>
      <CardContent><p className="font-display text-3xl font-semibold tracking-tight">{value}</p><p className="mt-2 text-xs text-muted-foreground">{helper}</p></CardContent>
    </Card>
  );
}

function IntakeLinkButton({ dealId, className }: { dealId?: number; className?: string }) {
  const createLink = trpc.intake.createLink.useMutation({
    onSuccess: result => copyShareLink(result.path, "Link para o corretor"),
    onError: error => toast.error(error.message),
  });
  return (
    <Button variant="outline" className={className} disabled={createLink.isPending} onClick={() => createLink.mutate({ dealId: dealId ?? null, source: "corretor" })}>
      {createLink.isPending ? <Loader2 className="size-4 animate-spin" /> : <Link2 className="size-4" />} Link para corretor
    </Button>
  );
}

function NewDealDialog({ trigger }: { trigger?: React.ReactNode }) {
  const [, setLocation] = useLocation();
  const utils = trpc.useUtils();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ title: "", transactionType: "venda" as TransactionType, propertyAddress: "", deadline: "", estimatedValue: "" });
  const createDeal = trpc.deals.create.useMutation({
    onSuccess: async result => {
      await Promise.all([utils.dashboard.get.invalidate(), utils.deals.list.invalidate()]);
      toast.success("Negócio criado. Agora você pode preencher os Dados do negócio e iniciar a análise.");
      setOpen(false);
      setLocation(`/negocios/${result.dealId}`);
    },
    onError: error => toast.error(error.message),
  });
  const update = (field: keyof typeof form, value: string) => setForm(current => ({ ...current, [field]: value }));
  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>{trigger ?? <Button><Plus className="size-4" /> Novo negócio</Button>}</DialogTrigger>
      <DialogContent className="sm:max-w-[560px]">
        <DialogHeader><DialogTitle className="font-display text-2xl">Abrir novo negócio</DialogTitle><DialogDescription>Crie o processo e conecte-o imediatamente aos Dados do negócio, aos documentos e ao painel do cliente.</DialogDescription></DialogHeader>
        <div className="grid gap-4 py-3">
          <div className="grid gap-2"><Label htmlFor="deal-title">Nome de referência</Label><Input id="deal-title" value={form.title} onChange={event => update("title", event.target.value)} placeholder="Ex.: Apartamento — Rua das Flores, 120" /></div>
          <div className="grid gap-2"><Label htmlFor="deal-type">Tipo de operação</Label><select id="deal-type" value={form.transactionType} onChange={event => update("transactionType", event.target.value)} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="venda">Compra e venda</option><option value="locacao">Locação</option><option value="outro">Outra operação</option></select></div>
          <div className="grid gap-2"><Label htmlFor="deal-address">Imóvel ou endereço</Label><Input id="deal-address" value={form.propertyAddress} onChange={event => update("propertyAddress", event.target.value)} placeholder="Informe a referência do imóvel" /></div>
          <div className="grid grid-cols-2 gap-4"><div className="grid gap-2"><Label htmlFor="deal-deadline">Prazo alvo</Label><Input id="deal-deadline" type="date" value={form.deadline} onChange={event => update("deadline", event.target.value)} /></div><div className="grid gap-2"><Label htmlFor="deal-value">Valor estimado</Label><Input id="deal-value" type="number" min="0" value={form.estimatedValue} onChange={event => update("estimatedValue", event.target.value)} placeholder="R$" /></div></div>
        </div>
        <DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={createDeal.isPending || !form.title.trim() || !form.propertyAddress.trim()} onClick={() => createDeal.mutate({ title: form.title, transactionType: form.transactionType, propertyAddress: form.propertyAddress, deadline: form.deadline ? new Date(`${form.deadline}T12:00:00`).toISOString() : null, estimatedValue: form.estimatedValue ? Number(form.estimatedValue) : null })}>{createDeal.isPending ? <Loader2 className="size-4 animate-spin" /> : <Plus className="size-4" />} Criar negócio</Button></DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

