export function DealsPage() {
  const [, setLocation] = useLocation();
  const [view, setView] = useState<"list" | "board">("list");
  const [search, setSearch] = useState("");
  const list = trpc.deals.list.useQuery();
  const filtered = (list.data ?? []).filter(deal => `${deal.title} ${deal.code} ${deal.propertyAddress}`.toLowerCase().includes(search.toLowerCase()));
  const stageColumns: DealStage[] = ["intake", "diligence", "draft", "internal_review", "client_review"];
  return <DashboardLayout><div className="page-shell">
    <PageHeader eyebrow="Central de negócios" title="Contratos em andamento" description="Cada negócio concentra os Dados do negócio, o contrato, os documentos de diligência, as obrigações e o acesso compartilhável do cliente." actions={<><IntakeLinkButton /><NewDealDialog /></>} />
    <div className="mb-5 flex flex-col justify-between gap-3 rounded-xl border border-border/80 bg-card p-3 sm:flex-row sm:items-center"><div className="relative w-full sm:max-w-md"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input value={search} onChange={event => setSearch(event.target.value)} className="pl-9" placeholder="Buscar código, imóvel ou parte" /></div><div className="flex gap-1 rounded-lg bg-muted p-1"><Button size="sm" variant={view === "list" ? "secondary" : "ghost"} onClick={() => setView("list")}>Lista</Button><Button size="sm" variant={view === "board" ? "secondary" : "ghost"} onClick={() => setView("board")}>Esteira</Button></div></div>
    {list.isLoading ? <div className="space-y-2"><div className="h-16 animate-pulse rounded-lg bg-muted" /><div className="h-16 animate-pulse rounded-lg bg-muted" /></div> : filtered.length === 0 ? <EmptyState icon={BriefcaseBusiness} title={search ? "Nenhum resultado encontrado" : "Nenhum negócio ativo"} description={search ? "Tente outro termo de busca." : "Os negócios serão preenchidos somente por criação manual ou por Dados do negócio preenchidos."} action={!search ? <div className="flex flex-wrap justify-center gap-2"><IntakeLinkButton /><NewDealDialog /></div> : undefined} /> : view === "list" ? <div className="overflow-hidden rounded-xl border border-border/80 bg-card"><div className="grid grid-cols-[minmax(240px,2.1fr)_minmax(100px,.55fr)_minmax(100px,.5fr)_minmax(120px,.6fr)_40px] gap-4 border-b bg-muted/30 px-5 py-3 text-[10px] font-bold uppercase tracking-[0.12em] text-muted-foreground"><span>Negócio</span><span>Etapa</span><span>Prazo</span><span>Atualização</span><span /></div>{filtered.map(deal => <button key={deal.id} onClick={() => setLocation(`/negocios/${deal.id}`)} className="grid w-full grid-cols-[minmax(240px,2.1fr)_minmax(100px,.55fr)_minmax(100px,.5fr)_minmax(120px,.6fr)_40px] gap-4 border-b border-border/70 px-5 py-4 text-left transition-colors last:border-0 hover:bg-muted/40"><span><strong className="block font-display text-base font-semibold tracking-tight">{deal.title}</strong><span className="mt-1 block truncate text-xs text-muted-foreground">{deal.code} · {deal.propertyAddress}</span></span><span className="self-center"><StageBadge stage={deal.stage as DealStage} /></span><span className="self-center text-sm text-muted-foreground">{formatDate(deal.deadline)}</span><span className="self-center text-sm text-muted-foreground">{formatDate(deal.updatedAt)}</span><ChevronRight className="self-center text-muted-foreground" /></button>)}</div> : <div className="overflow-x-auto pb-3"><div className="grid min-w-[1120px] grid-cols-5 gap-4">{stageColumns.map(stage => <section key={stage} className="rounded-xl border border-border/70 bg-muted/30 p-3"><div className="mb-3 flex items-center justify-between px-1"><span className="text-xs font-bold uppercase tracking-[0.12em] text-muted-foreground">{stageMeta[stage].label}</span><span className="text-xs text-muted-foreground">{filtered.filter(deal => deal.stage === stage).length}</span></div><div className="space-y-3">{filtered.filter(deal => deal.stage === stage).map(deal => <button key={deal.id} onClick={() => setLocation(`/negocios/${deal.id}`)} className="w-full rounded-lg border border-border/80 bg-card p-4 text-left shadow-sm transition hover:shadow-md"><StageBadge stage={deal.stage as DealStage} /><p className="mt-3 font-display text-base font-semibold leading-5 tracking-tight">{deal.title}</p><p className="mt-1 text-xs text-muted-foreground">{deal.code}</p><p className="mt-4 text-xs text-muted-foreground">{formatDate(deal.deadline)}</p></button>)}{!filtered.some(deal => deal.stage === stage) ? <div className="rounded-lg border border-dashed border-border px-3 py-6 text-center text-xs text-muted-foreground">Sem negócios nesta etapa.</div> : null}</div></section>)}</div></div>}
  </div></DashboardLayout>;
}

type ProposalPartyForm = { role: "vendedor" | "comprador" | "locador" | "locatario" | "corretor" | "parceiro" | "outro"; name: string; document: string; email: string; phone: string; commissionAmount: string };
type ProposalForm = { title: string; transactionType: TransactionType; propertyAddress: string; propertyIdentification: string; offerAmount: string; paymentMethod: string; paymentFlow: string; conditions: string; expiresAt: string; recipientName: string; futureParties: ProposalPartyForm[] };
const proposalStatuses = { rascunho: { label: "Rascunho", className: "border-zinc-200 bg-zinc-50 text-zinc-700" }, enviada: { label: "Enviada", className: "border-blue-200 bg-blue-50 text-blue-800" }, aceita: { label: "Aceita", className: "border-emerald-200 bg-emerald-50 text-emerald-800" }, recusada: { label: "Recusada", className: "border-red-200 bg-red-50 text-red-800" }, convertida: { label: "Convertida", className: "border-violet-200 bg-violet-50 text-violet-800" } } as const;
const partyRoleLabels = { vendedor: "Vendedor", comprador: "Comprador", locador: "Locador", locatario: "Locatário", corretor: "Corretor", parceiro: "Parceiro", outro: "Outra parte" } as const;
const emptyProposalForm = (): ProposalForm => ({ title: "", transactionType: "venda", propertyAddress: "", propertyIdentification: "", offerAmount: "", paymentMethod: "", paymentFlow: "", conditions: "", expiresAt: "", recipientName: "", futureParties: [] });

function BrokerProposalEditLink({ proposalId }: { proposalId: number }) {
  const createLink = trpc.proposals.createBrokerLink.useMutation({ onSuccess: result => copyShareLink(result.path, "Link de edição para o corretor"), onError: error => toast.error(error.message) });
  return <Button type="button" size="sm" variant="outline" disabled={createLink.isPending} onClick={() => createLink.mutate({ proposalId })}>{createLink.isPending ? <Loader2 className="size-3.5 animate-spin" /> : <Link2 className="size-3.5" />} Link para corretor</Button>;
}

function ProposalDialog({ proposal, trigger }: { proposal?: { id: number; title: string; transactionType: TransactionType; propertyAddress: string; propertyIdentification: string | null; offerAmount: number | null; paymentMethod: string | null; paymentFlow: string | null; conditions: string | null; expiresAt: Date | string | null; recipientName: string | null; futureParties: unknown; status: keyof typeof proposalStatuses }; trigger?: React.ReactNode }) {
  const utils = trpc.useUtils();
  const [open, setOpen] = useState(false);
  const initial = (): ProposalForm => proposal ? { title: proposal.title, transactionType: proposal.transactionType, propertyAddress: proposal.propertyAddress, propertyIdentification: proposal.propertyIdentification ?? "", offerAmount: proposal.offerAmount?.toString() ?? "", paymentMethod: proposal.paymentMethod ?? "", paymentFlow: proposal.paymentFlow ?? "", conditions: proposal.conditions ?? "", expiresAt: dateInputValue(proposal.expiresAt), recipientName: proposal.recipientName ?? "", futureParties: Array.isArray(proposal.futureParties) ? proposal.futureParties.map(item => { const party = item as Partial<ProposalPartyForm>; return { role: party.role ?? "vendedor", name: party.name ?? "", document: party.document ?? "", email: party.email ?? "", phone: party.phone ?? "", commissionAmount: party.commissionAmount?.toString() ?? "" }; }) : [] } : emptyProposalForm();
  const [form, setForm] = useState<ProposalForm>(initial);
  const save = async (result: { proposalId: number }) => { await utils.proposals.list.invalidate(); setOpen(false); toast.success(proposal ? "Proposta atualizada." : "Proposta criada em rascunho."); return result; };
  const create = trpc.proposals.create.useMutation({ onSuccess: save, onError: error => toast.error(error.message) });
  const update = trpc.proposals.update.useMutation({ onSuccess: () => save({ proposalId: proposal?.id ?? 0 }), onError: error => toast.error(error.message) });
  const addParty = (role: ProposalPartyForm["role"]) => setForm(current => ({ ...current, futureParties: [...current.futureParties, { role, name: "", document: "", email: "", phone: "", commissionAmount: "" }] }));
  const updateParty = (index: number, field: keyof ProposalPartyForm, value: string) => setForm(current => ({ ...current, futureParties: current.futureParties.map((party, partyIndex) => partyIndex === index ? { ...party, [field]: value } : party) }));
  const submit = () => {
    const futureParties = form.futureParties.map(party => ({ role: party.role, name: party.name, document: party.document || undefined, email: party.email || undefined, phone: party.phone || undefined, commissionAmount: party.commissionAmount ? Number(party.commissionAmount) : undefined }));
    const payload = { title: form.title, transactionType: form.transactionType, propertyAddress: form.propertyAddress, propertyIdentification: form.propertyIdentification || undefined, offerAmount: form.offerAmount ? Number(form.offerAmount) : null, paymentMethod: form.paymentMethod || undefined, paymentFlow: form.paymentFlow || undefined, conditions: form.conditions || undefined, expiresAt: form.expiresAt ? new Date(`${form.expiresAt}T12:00:00`).toISOString() : null, recipientName: form.recipientName || undefined, futureParties };
    if (proposal) update.mutate({ ...payload, proposalId: proposal.id }); else create.mutate(payload);
  };
  const busy = create.isPending || update.isPending;
  const setField = (field: Exclude<keyof ProposalForm, "futureParties">, value: string) => setForm(current => ({ ...current, [field]: value }));
  return <Dialog open={open} onOpenChange={next => { setOpen(next); if (next) setForm(initial()); }}><DialogTrigger asChild>{trigger ?? <Button><Plus className="size-4" /> Nova proposta</Button>}</DialogTrigger><DialogContent className="max-h-[88vh] overflow-y-auto sm:max-w-[780px]"><DialogHeader><DialogTitle className="font-display text-2xl">{proposal ? "Editar proposta" : "Nova proposta"}</DialogTitle><DialogDescription>Estruture a oferta antes de criar o negócio. Os campos podem ser complementados pelas partes no link seguro.</DialogDescription></DialogHeader><div className="grid gap-5 py-3"><div className="grid gap-4 md:grid-cols-2"><div className="grid gap-2"><Label>Nome de referência</Label><Input value={form.title} onChange={event => setField("title", event.target.value)} placeholder="Ex.: Proposta · Apartamento Centro" /></div><div className="grid gap-2"><Label>Tipo de operação</Label><select value={form.transactionType} onChange={event => setField("transactionType", event.target.value)} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="venda">Compra e venda</option><option value="locacao">Locação</option><option value="outro">Outra operação</option></select></div></div><div className="rounded-xl border bg-muted/20 p-4"><p className="text-sm font-semibold">Imóvel e condições comerciais</p><div className="mt-4 grid gap-4"><div className="grid gap-2"><Label>Endereço ou referência do imóvel</Label><Input value={form.propertyAddress} onChange={event => setField("propertyAddress", event.target.value)} placeholder="Rua, número, unidade e cidade" /></div><div className="grid gap-2"><Label>Identificação do imóvel</Label><Input value={form.propertyIdentification} onChange={event => setField("propertyIdentification", event.target.value)} placeholder="Matrícula, inscrição ou outra referência" /></div><div className="grid gap-4 md:grid-cols-3"><div className="grid gap-2"><Label>Valor proposto</Label><Input type="number" min="0" value={form.offerAmount} onChange={event => setField("offerAmount", event.target.value)} placeholder="R$" /></div><div className="grid gap-2"><Label>Forma de pagamento</Label><Input value={form.paymentMethod} onChange={event => setField("paymentMethod", event.target.value)} placeholder="Ex.: financiamento" /></div><div className="grid gap-2"><Label>Validade</Label><Input type="date" value={form.expiresAt} onChange={event => setField("expiresAt", event.target.value)} /></div></div><div className="grid gap-2"><Label>Fluxo de pagamento</Label><Textarea value={form.paymentFlow} onChange={event => setField("paymentFlow", event.target.value)} className="min-h-20" placeholder="Sinal, parcelas, financiamento, prazo e condições de liberação..." /></div><div className="grid gap-2"><Label>Condições e observações</Label><Textarea value={form.conditions} onChange={event => setField("conditions", event.target.value)} className="min-h-20" placeholder="Condições suspensivas, documentos, despesas, posse ou demais condições..." /></div></div></div><div className="rounded-xl border p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-semibold">Futuras partes do negócio</p><p className="mt-1 text-xs text-muted-foreground">Inclua quem receberá ou participará da proposta.</p></div><div className="flex flex-wrap gap-2"><Button type="button" size="sm" variant="outline" onClick={() => addParty(form.transactionType === "locacao" ? "locador" : "vendedor")}><Plus className="size-3.5" /> {form.transactionType === "locacao" ? "Locador" : "Vendedor"}</Button><Button type="button" size="sm" variant="outline" onClick={() => addParty(form.transactionType === "locacao" ? "locatario" : "comprador")}><Plus className="size-3.5" /> {form.transactionType === "locacao" ? "Locatário" : "Comprador"}</Button><Button type="button" size="sm" variant="outline" onClick={() => addParty("corretor")}><Plus className="size-3.5" /> Corretor</Button></div></div><div className="mt-4 space-y-3">{form.futureParties.map((party, index) => <div key={`${party.role}-${index}`} className="rounded-lg border bg-muted/20 p-3"><div className="mb-3 flex items-center justify-between"><select value={party.role} onChange={event => updateParty(index, "role", event.target.value)} className="h-8 rounded border bg-background px-2 text-xs">{Object.entries(partyRoleLabels).map(([role, label]) => <option key={role} value={role}>{label}</option>)}</select><Button type="button" size="sm" variant="ghost" className="text-destructive hover:text-destructive" onClick={() => setForm(current => ({ ...current, futureParties: current.futureParties.filter((_, partyIndex) => partyIndex !== index) }))}>Remover</Button></div><div className="grid gap-3 sm:grid-cols-2"><Input value={party.name} onChange={event => updateParty(index, "name", event.target.value)} placeholder="Nome ou razão social" /><Input value={party.document} onChange={event => updateParty(index, "document", event.target.value)} placeholder="CPF ou CNPJ" /><Input value={party.email} onChange={event => updateParty(index, "email", event.target.value)} placeholder="E-mail" /><Input value={party.phone} onChange={event => updateParty(index, "phone", event.target.value)} placeholder="Telefone" />{(party.role === "corretor" || party.role === "parceiro") ? <Input type="number" min="0" value={party.commissionAmount} onChange={event => updateParty(index, "commissionAmount", event.target.value)} placeholder="Comissão (R$)" /> : null}</div></div>)}{!form.futureParties.length ? <p className="rounded-lg border border-dashed px-3 py-5 text-center text-xs text-muted-foreground">As partes podem ser incluídas agora ou complementadas no link compartilhável.</p> : null}</div></div><div className="grid gap-2"><Label>Nome do destinatário principal</Label><Input value={form.recipientName} onChange={event => setField("recipientName", event.target.value)} placeholder="Opcional — para personalizar o link da proposta" /></div></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={busy || !form.title.trim() || !form.propertyAddress.trim()} onClick={submit}>{busy ? <Loader2 className="size-4 animate-spin" /> : <FileText className="size-4" />} {proposal ? "Salvar alterações" : "Salvar proposta"}</Button></DialogFooter></DialogContent></Dialog>;
}

export function ProposalsPage() {
  const [, setLocation] = useLocation();
  const utils = trpc.useUtils();
  const list = trpc.proposals.list.useQuery();
  const share = trpc.proposals.share.useMutation({ onSuccess: async result => { await copyShareLink(result.path, "Link da proposta"); await utils.proposals.list.invalidate(); }, onError: error => toast.error(error.message) });
  const brokerLink = trpc.proposals.createBrokerLink.useMutation({ onSuccess: result => copyShareLink(result.path, "Link de edição para o corretor"), onError: error => toast.error(error.message) });
  const convert = trpc.proposals.convertToDeal.useMutation({ onSuccess: async result => { await Promise.all([utils.proposals.list.invalidate(), utils.deals.list.invalidate(), utils.dashboard.get.invalidate()]); toast.success("Proposta convertida em negócio. Complete os Dados do negócio para elaborar a minuta."); setLocation(result.path); }, onError: error => toast.error(error.message) });
  const items = list.data ?? [];
  const count = (status: keyof typeof proposalStatuses) => items.filter(item => item.status === status).length;
  return <DashboardLayout><div className="page-shell"><PageHeader eyebrow="Pré-negociação" title="Central de Propostas" description="Estruture valores, imóvel, fluxo de pagamento e futuras partes antes de iniciar o negócio. Compartilhe uma proposta segura para manifestação." actions={<ProposalDialog />} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard icon={FileText} label="Rascunhos" value={count("rascunho")} helper="Em preparação interna" accent="bg-zinc-400" /><MetricCard icon={Share2} label="Enviadas" value={count("enviada")} helper="Aguardando manifestação" accent="bg-blue-500" /><MetricCard icon={Check} label="Aceitas" value={count("aceita")} helper="Prontas para virar negócio" accent="bg-emerald-500" /><MetricCard icon={BriefcaseBusiness} label="Convertidas" value={count("convertida")} helper="Já vinculadas à operação" accent="bg-violet-500" /></div><section className="mt-8"><div className="mb-4"><p className="section-kicker">Propostas comerciais</p><h2 className="font-display text-2xl font-semibold tracking-tight">Ofertas em acompanhamento</h2></div>{list.isLoading ? <div className="space-y-3"><div className="h-28 animate-pulse rounded-xl bg-muted" /><div className="h-28 animate-pulse rounded-xl bg-muted" /></div> : items.length ? <div className="grid gap-3">{items.map(item => { const status = proposalStatuses[item.status as keyof typeof proposalStatuses]; return <Card key={item.id} className="border-border/80"><CardContent className="p-5"><div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><Badge variant="outline" className={status.className}>{status.label}</Badge><span className="text-xs text-muted-foreground">{item.code}</span>{item.expiresAt ? <span className="text-xs text-muted-foreground">Válida até {formatDate(item.expiresAt)}</span> : null}</div><h3 className="mt-3 font-display text-lg font-semibold tracking-tight">{item.title}</h3><p className="mt-1 text-sm text-muted-foreground">{item.propertyAddress}</p><div className="mt-3 flex flex-wrap gap-x-5 gap-y-1 text-xs text-muted-foreground"><span>Valor: <strong className="text-foreground">{formatMoney(item.offerAmount)}</strong></span><span>{item.paymentMethod ?? "Forma de pagamento a definir"}</span><span>{Array.isArray(item.futureParties) ? `${item.futureParties.length} futura${item.futureParties.length === 1 ? " parte" : "s partes"}` : "Partes a definir"}</span></div></div><div className="flex flex-wrap gap-2"><ProposalDialog key={item.id} proposal={{ ...item, transactionType: item.transactionType as TransactionType, status: item.status as keyof typeof proposalStatuses }} trigger={<Button variant="outline">Editar</Button>} />{item.status !== "convertida" ? <Button variant="outline" disabled={share.isPending} onClick={() => share.mutate({ proposalId: item.id })}>{share.isPending ? <Loader2 className="size-4 animate-spin" /> : <Link2 className="size-4" />} Copiar link</Button> : null}{item.status === "aceita" ? <Button disabled={convert.isPending} onClick={() => convert.mutate({ proposalId: item.id })}>{convert.isPending ? <Loader2 className="size-4 animate-spin" /> : <ArrowRight className="size-4" />} Criar negócio</Button> : null}{item.status === "convertida" && item.dealId ? <Button variant="outline" onClick={() => setLocation(`/negocios/${item.dealId}`)}>Abrir negócio <ArrowRight className="size-4" /></Button> : null}</div></div></CardContent></Card>; })}</div> : <EmptyState icon={FileText} title="Nenhuma proposta criada" description="Inicie uma proposta para organizar a oferta antes de criar o negócio ou encaminhá-la às futuras partes." action={<ProposalDialog />} />}</section></div></DashboardLayout>;
}

