function TabButton({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) {
  return <button onClick={onClick} className={`border-b-2 px-1 py-3 text-sm font-medium transition-colors ${active ? "border-foreground text-foreground" : "border-transparent text-muted-foreground hover:text-foreground"}`}>{children}</button>;
}

export function DealPanelPage() {
  const [, params] = useRoute("/negocios/:id");
  const [, setLocation] = useLocation();
  const dealId = Number(params?.id);
  const detail = trpc.deals.get.useQuery({ dealId }, { enabled: Number.isFinite(dealId) });
  const utils = trpc.useUtils();
  const [tab, setTab] = useState(() => {
    const requested = new URLSearchParams(window.location.search).get("aba");
    if (requested === "topicos") return "guiado";
    if (requested === "intakes") return "dados";
    return ["visao", "esteira", "dados", "guiado", "diligencia", "dossie", "cliente"].includes(requested ?? "") ? requested! : "visao";
  });
  const archive = trpc.deals.archive.useMutation({ onSuccess: async () => { await Promise.all([utils.deals.list.invalidate(), utils.dashboard.get.invalidate()]); toast.success("Processo arquivado com sucesso."); setLocation("/arquivo"); }, onError: error => toast.error(error.message) });
  if (detail.isLoading) return <DashboardLayout><div className="page-shell"><div className="h-10 w-52 animate-pulse rounded bg-muted" /><div className="mt-8 h-64 animate-pulse rounded-xl bg-muted" /></div></DashboardLayout>;
  if (!detail.data) return <DashboardLayout><div className="page-shell"><EmptyState icon={BriefcaseBusiness} title="Negócio não encontrado" description="Este processo não está acessível neste ambiente." action={<Button onClick={() => setLocation("/negocios")}>Voltar para negócios</Button>} /></div></DashboardLayout>;
  const { deal, intakes, checklist, documents, contracts, obligations: dealObligations, parties, analyses, reviewLinks, reviewComments, workItems, events } = detail.data;
  const approved = checklist.filter(item => item.status === "aprovado" || item.status === "dispensado").length;
  const progress = checklist.length ? Math.round((approved / checklist.length) * 100) : 0;
  const currentContract = contracts[0];
  const contractProgress = getContractProgress(currentContract?.status);
  return <DashboardLayout><div className="page-shell">
    <button onClick={() => setLocation("/negocios")} className="mb-7 inline-flex items-center gap-2 text-sm font-medium text-muted-foreground transition hover:text-foreground"><ArrowLeft className="size-4" /> Voltar para negócios</button>
    <PageHeader eyebrow={`Painel do negócio · ${deal.code}`} title={deal.title} description={`${deal.propertyAddress} · ${deal.transactionType === "venda" ? "Compra e venda" : deal.transactionType === "locacao" ? "Locação" : "Outra operação"}`} actions={<><IntakeLinkButton dealId={deal.id} /><Button variant="outline" onClick={() => copyShareLink(`/cliente/${deal.clientToken}`, "Link do painel do cliente")}><Copy className="size-4" /> Link do cliente</Button><Button variant="outline" className="text-destructive hover:text-destructive" disabled={archive.isPending} onClick={() => archive.mutate({ dealId: deal.id })}><FolderArchive className="size-4" /> Arquivar</Button></>} />
    <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><MetricCard icon={BriefcaseBusiness} label="Valor do negócio" value={formatMoney(deal.estimatedValue)} helper="Valor informado nos Dados do negócio" /><MetricCard icon={FileCheck2} label="Dossiê" value={`${documents.length} anexo${documents.length === 1 ? "" : "s"}`} helper={`${checklist.length} itens de diligência`} accent="bg-emerald-500" /><MetricCard icon={MessageSquareMore} label="Revisões" value={contracts.length ? contracts[0].version : 0} helper={contracts.length ? "Versão contratual atual" : "Contrato ainda não iniciado"} accent="bg-violet-500" /><MetricCard icon={CalendarClock} label="Próximo prazo" value={dealObligations[0] ? formatDate(dealObligations[0].dueAt) : "A definir"} helper={dealObligations[0]?.title ?? "Sem obrigação registrada"} accent="bg-amber-500" /></div>
    <Card className="mt-5 border-border/80"><CardContent className="p-5"><div className="mb-5 flex flex-col gap-2 md:flex-row md:items-end md:justify-between"><div><p className="section-kicker">Leitura de andamento</p><h2 className="font-display text-xl font-semibold tracking-tight">Progresso do processo</h2></div><StageBadge stage={deal.stage as DealStage} /></div><div className="grid gap-5 md:grid-cols-2"><div><div className="mb-2 flex items-center justify-between text-sm"><span className="inline-flex items-center gap-2 font-semibold"><FileText className="size-4" /> Contrato</span><span className="text-muted-foreground">{contractProgress}% · {currentContract ? currentContract.status.replaceAll("_", " ") : "não iniciado"}</span></div><Progress value={contractProgress} className="h-2" /></div><div><div className="mb-2 flex items-center justify-between text-sm"><span className="inline-flex items-center gap-2 font-semibold"><ClipboardCheck className="size-4" /> Due diligence</span><span className="text-muted-foreground">{progress}% · {approved}/{checklist.length || 0} itens</span></div><Progress value={progress} className="h-2" /></div></div><div className="mt-5 grid gap-2 sm:grid-cols-4">{["Dados", "Diligência", "Minuta", "Revisão"].map((label, index) => { const completed = index === 0 ? intakes.some(item => item.submittedAt) : index === 1 ? progress === 100 : index === 2 ? contractProgress >= 25 : contractProgress >= 60; return <div key={label} className={`flex items-center gap-2 rounded-lg border px-3 py-2 text-xs font-medium ${completed ? "border-foreground bg-foreground text-background" : "border-border text-muted-foreground"}`}><span className={`flex size-5 items-center justify-center rounded-full text-[10px] ${completed ? "bg-white/20" : "bg-muted"}`}>{completed ? <Check className="size-3" /> : index + 1}</span>{label}</div>; })}</div></CardContent></Card>
    <div className="mt-8 border-b border-border"><div className="flex gap-6 overflow-x-auto"><TabButton active={tab === "visao"} onClick={() => setTab("visao")}>Visão do processo</TabButton><TabButton active={tab === "esteira"} onClick={() => setTab("esteira")}>Esteira</TabButton><TabButton active={tab === "dados"} onClick={() => setTab("dados")}>Dados do negócio</TabButton><TabButton active={tab === "guiado"} onClick={() => setTab("guiado")}>Tópicos jurídicos</TabButton><TabButton active={tab === "diligencia"} onClick={() => setTab("diligencia")}>Due diligence</TabButton><TabButton active={tab === "dossie"} onClick={() => setTab("dossie")}>Dossiê</TabButton><TabButton active={tab === "cliente"} onClick={() => setTab("cliente")}>Painel do cliente</TabButton></div></div>
    <div className="pt-7">{tab === "visao" ? <DealOverview dealId={deal.id} intakeCount={intakes.length} contractCount={contracts.length} documentCount={documents.length} progress={progress} onTab={setTab} /> : null}{tab === "esteira" ? <OperationsBoard dealId={deal.id} workItems={workItems} events={events} /> : null}{tab === "dados" ? <DealDataWorkspace dealId={deal.id} transactionType={deal.transactionType as TransactionType} /> : null}{tab === "guiado" ? <GuidedContractComposer dealId={deal.id} contracts={contracts} /> : null}{tab === "diligencia" ? <DiligenceDocumentWorkspace dealId={deal.id} checklist={checklist} documents={documents} analyses={analyses} /> : null}{tab === "dossie" ? <DossierWorkspace dealId={deal.id} documents={documents} /> : null}{tab === "cliente" ? <ClientPanelShare deal={deal} documents={documents} /> : null}</div>
  </div></DashboardLayout>;
}

function DealOverview({ dealId, intakeCount, contractCount, documentCount, progress, onTab }: { dealId: number; intakeCount: number; contractCount: number; documentCount: number; progress: number; onTab: (tab: string) => void }) {
  const cards = [{ icon: FileText, title: "Dados do negócio", text: intakeCount ? `${intakeCount} registro de informações disponível.` : "Preencha diretamente ou compartilhe o link opcional com o corretor.", tab: "dados" }, { icon: Scale, title: "Contrato", text: contractCount ? "Minuta em elaboração com versionamento." : "Selecione um modelo e prepare a minuta do contrato.", tab: "guiado" }, { icon: ClipboardCheck, title: "Due diligence", text: documentCount ? `${documentCount} documento${documentCount === 1 ? "" : "s"} no dossiê.` : "Monte a lista de certidões e anexe os comprovantes.", tab: "diligencia" }];
  return <div className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_360px]"><Card className="border-border/80"><CardHeader><p className="section-kicker">Camadas do negócio</p><CardTitle className="font-display text-2xl tracking-tight">Trabalho concentrado no mesmo processo</CardTitle><CardDescription>Os Dados do negócio alimentam o contexto documental e contratual desta operação.</CardDescription></CardHeader><CardContent className="grid gap-3 md:grid-cols-3">{cards.map(card => <button key={card.title} onClick={() => onTab(card.tab)} className="rounded-xl border border-border/80 p-5 text-left transition hover:border-foreground/20 hover:bg-muted/30"><card.icon className="size-5" /><h3 className="mt-6 font-display text-lg font-semibold tracking-tight">{card.title}</h3><p className="mt-2 min-h-10 text-sm leading-5 text-muted-foreground">{card.text}</p><span className="mt-5 inline-flex items-center gap-1 text-sm font-medium">Abrir <ArrowRight className="size-4" /></span></button>)}</CardContent></Card><Card className="overflow-hidden border-0 bg-[#19171d] text-white"><CardContent className="p-6"><div className="flex size-10 items-center justify-center rounded-xl bg-violet-300/10 text-violet-200"><ShieldCheck className="size-5" /></div><p className="mt-6 text-[10px] font-bold uppercase tracking-[0.16em] text-zinc-400">Dossiê de diligência</p><h2 className="mt-2 font-display text-2xl font-semibold tracking-tight">Prontidão do processo</h2><p className="mt-2 text-sm leading-6 text-zinc-300">Acompanhe o percentual de itens verificados antes de compartilhar a documentação com o cliente.</p><div className="mt-7"><div className="mb-2 flex items-center justify-between text-sm"><span>{progress}% concluído</span><span className="text-zinc-400">Diligência</span></div><Progress value={progress} className="h-2 bg-white/10" /></div><Button className="mt-7 w-full bg-white text-zinc-900 hover:bg-zinc-100" onClick={() => onTab("diligencia")}>Abrir checklist <ArrowRight className="size-4" /></Button></CardContent></Card></div>;
}

function DealDataWorkspace({ dealId, transactionType }: { dealId: number; transactionType: TransactionType }) {
  const data = trpc.intake.getForDeal.useQuery({ dealId });
  if (data.isLoading) return <div className="h-[680px] animate-pulse rounded-xl bg-muted" />;
  return <section><div className="mb-5 flex justify-end"><IntakeLinkButton dealId={dealId} /></div><ContractIntakeForm dealId={dealId} transactionType={transactionType} initialData={data.data?.initialData} initiallyComplete={data.data?.isComplete} mode="interno" /></section>;
}

function ContractEditor({ dealId, contracts: currentContracts, deal, reviewLinks, reviewComments }: { dealId: number; contracts: Array<{ id: number; title: string; content: string; status: "rascunho" | "revisao_interna" | "revisao_cliente" | "finalizado"; version: number }>; deal: { title: string; propertyAddress: string; transactionType: TransactionType }; reviewLinks: Array<{ id: number; contractId: number; contractVersion: number; status: "ativo" | "enviado" | "revogado"; expiresAt: Date | string; approvedAt: Date | string | null; approvedBy: string | null }>; reviewComments: Array<{ id: number; reviewLinkId: number; authorName: string; content: string; selectedText: string | null; status: "novo" | "resolvido"; createdAt: Date | string }> }) {
  const utils = trpc.useUtils();
  const templates = trpc.templates.list.useQuery();
  const [selectedTemplate, setSelectedTemplate] = useState("");
  const [fieldValues, setFieldValues] = useState<Record<string, string>>({});
  const [content, setContent] = useState("");
  const [status, setStatus] = useState<"rascunho" | "revisao_interna" | "revisao_cliente" | "finalizado">("rascunho");
  const activeContract = currentContracts[0];
  useEffect(() => { if (activeContract) { setContent(activeContract.content); setStatus(activeContract.status); } }, [activeContract?.id]);
  const save = trpc.contracts.update.useMutation({ onSuccess: async () => { await utils.deals.get.invalidate({ dealId }); toast.success("Minuta atualizada e versionada no processo."); }, onError: error => toast.error(error.message) });
  const create = trpc.contracts.create.useMutation({ onSuccess: async () => { await utils.deals.get.invalidate({ dealId }); toast.success("Minuta criada com base no modelo selecionado."); }, onError: error => toast.error(error.message) });
  const createReviewLink = trpc.contracts.createReviewLink.useMutation({ onSuccess: async result => { await utils.deals.get.invalidate({ dealId }); await copyShareLink(result.path, "Link seguro de revisão"); toast.success(result.reused ? "Link de revisão existente copiado." : "Link de revisão criado para o cliente."); }, onError: error => toast.error(error.message) });
  const resolveComment = trpc.contractReview.resolveComment.useMutation({ onSuccess: () => { utils.deals.get.invalidate({ dealId }); toast.success("Comentário marcado como resolvido."); }, onError: error => toast.error(error.message) });
  const selectedTemplateDefinition = templates.data?.find(item => item.id === Number(selectedTemplate));
  const mappedFields = Array.isArray(selectedTemplateDefinition?.fields) ? selectedTemplateDefinition.fields.filter((field): field is string => typeof field === "string") : [];
  const chooseTemplate = (templateId: string) => { setSelectedTemplate(templateId); const template = templates.data?.find(item => item.id === Number(templateId)); const fields = Array.isArray(template?.fields) ? template.fields.filter((field): field is string => typeof field === "string") : []; setFieldValues(Object.fromEntries(fields.map(field => [field, field === "NEGOCIO" ? deal.title : field === "IMOVEL" ? deal.propertyAddress : ""]))); };
  const startTemplate = () => { const template = templates.data?.find(item => item.id === Number(selectedTemplate)); if (!template) { toast.error("Selecione um modelo de contrato configurado."); return; } const rendered = template.content.replace(/{{\s*([^}]+)\s*}}/g, (_match, fieldName: string) => fieldValues[fieldName] || `{{${fieldName}}}`); setContent(rendered); toast.success("Modelo carregado para revisão."); };
  const saveContract = () => { if (activeContract) { save.mutate({ dealId, contractId: activeContract.id, content, status }); return; } create.mutate({ dealId, templateId: Number(selectedTemplate), title: `Minuta — ${deal.title}`, content }); };
  const contractComments = activeContract ? reviewComments.filter(comment => reviewLinks.some(link => link.id === comment.reviewLinkId && link.contractId === activeContract.id)) : [];
  return <section><div className="mb-5 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p className="section-kicker">Elaboração contratual</p><h2 className="font-display text-2xl font-semibold tracking-tight">{activeContract ? activeContract.title : "Prepare uma minuta"}</h2><p className="mt-1 text-sm text-muted-foreground">Editor interno com conteúdo livre, modelos configuráveis e estados de revisão.</p></div><div className="flex flex-wrap gap-2"><select value={status} onChange={event => setStatus(event.target.value as typeof status)} className="h-9 rounded-md border bg-background px-3 text-sm"><option value="rascunho">Rascunho</option><option value="revisao_interna">Revisão interna</option><option value="revisao_cliente">Revisão do cliente</option><option value="finalizado">Finalizado</option></select>{activeContract ? <Button variant="outline" disabled={createReviewLink.isPending} onClick={() => createReviewLink.mutate({ dealId, contractId: activeContract.id })}>{createReviewLink.isPending ? <Loader2 className="size-4 animate-spin" /> : <Share2 className="size-4" />} Compartilhar revisão</Button> : null}<Button disabled={!content.trim() || save.isPending || create.isPending} onClick={saveContract}>{save.isPending || create.isPending ? <Loader2 className="size-4 animate-spin" /> : <><Check className="size-4" /> {activeContract ? "Salvar versão" : "Criar minuta"}</>}</Button></div></div>
    {!activeContract ? <Card className="mb-5 border-violet-200 bg-violet-50/50"><CardContent className="flex flex-col gap-4 p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-end"><div className="flex-1"><Label className="text-violet-950">Modelo contratual</Label><select value={selectedTemplate} onChange={event => chooseTemplate(event.target.value)} className="mt-2 h-10 w-full rounded-md border border-violet-200 bg-white px-3 text-sm"><option value="">Selecione um modelo configurado</option>{templates.data?.filter(template => template.transactionType === deal.transactionType || template.transactionType === "outro").map(template => <option key={template.id} value={template.id}>{template.name} · v{template.version}{template.sourceFileName ? " · Word" : ""}</option>)}</select><p className="mt-2 text-xs text-violet-800">Não há modelos pré-carregados. Cadastre seus modelos em Configurações para gerar a minuta.</p></div><Button variant="outline" className="border-violet-200 bg-white" onClick={startTemplate}>Carregar modelo <ArrowRight className="size-4" /></Button></div>{selectedTemplateDefinition?.sourceFileUrl ? <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-violet-200 bg-white/70 px-3 py-2 text-sm"><span className="flex items-center gap-2 font-medium text-violet-950"><FileText className="size-4" />Modelo importado de Word</span><a href={selectedTemplateDefinition.sourceFileUrl} target="_blank" rel="noreferrer" className="font-semibold underline underline-offset-4">Abrir original: {selectedTemplateDefinition.sourceFileName ?? "DOCX"}</a></div> : null}{mappedFields.length ? <div className="grid gap-3 border-t border-violet-200/80 pt-4 md:grid-cols-2">{mappedFields.map(field => <div key={field} className="grid gap-1.5"><Label className="text-xs text-violet-950">{field.replaceAll("_", " ")}</Label><Input value={fieldValues[field] ?? ""} onChange={event => setFieldValues(current => ({ ...current, [field]: event.target.value }))} placeholder={`Preencher ${field.replaceAll("_", " ").toLowerCase()}`} /></div>)}</div> : null}</CardContent></Card> : null}
    <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_280px]"><Card className="border-border/80"><CardContent className="p-0"><div className="flex items-center justify-between border-b px-5 py-3"><span className="text-xs font-semibold text-muted-foreground">EDITOR DE MINUTA</span><span className="text-xs text-muted-foreground">{content.length.toLocaleString("pt-BR")} caracteres</span></div><Textarea value={content} onChange={event => setContent(event.target.value)} className="min-h-[570px] resize-y border-0 bg-white p-7 font-mono text-[13px] leading-7 shadow-none focus-visible:ring-0" placeholder="Selecione um modelo de contrato ou comece a redigir a minuta..." /></CardContent></Card><div className="space-y-4"><Card className="border-border/80"><CardHeader className="pb-3"><CardTitle className="font-display text-lg">Comentários do cliente</CardTitle></CardHeader><CardContent className="space-y-3 text-sm">{contractComments.length ? contractComments.map(comment => <div key={comment.id} className="rounded-lg border p-3"><div className="flex items-start justify-between gap-3"><p className="font-semibold">{comment.authorName}</p><Badge variant="outline" className="text-[10px]">{comment.status}</Badge></div>{comment.selectedText ? <blockquote className="mt-2 border-l-2 border-violet-400 bg-violet-50 px-2 py-1 text-xs leading-5 text-violet-950">“{comment.selectedText}”</blockquote> : null}<p className="mt-2 leading-5 text-muted-foreground">{comment.content}</p>{comment.status === "novo" ? <Button variant="ghost" size="sm" className="mt-2 h-7 px-2" onClick={() => resolveComment.mutate({ dealId, commentId: comment.id })}>Marcar resolvido</Button> : null}</div>) : <p className="leading-6 text-muted-foreground">Os comentários enviados pelo cliente serão listados aqui.</p>}{reviewLinks.some(link => activeContract && link.contractId === activeContract.id && link.approvedAt) ? <div className="rounded-lg border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-900"><strong>Minuta aprovada.</strong><br />{reviewLinks.find(link => activeContract && link.contractId === activeContract.id && link.approvedAt)?.approvedBy ?? "Cliente"} confirmou a versão compartilhada.</div> : null}</CardContent></Card><Card className="border-border/80"><CardHeader className="pb-3"><CardTitle className="font-display text-lg">Revisão guiada</CardTitle></CardHeader><CardContent className="space-y-4 text-sm text-muted-foreground"><p>Revise com o Copiloto Jurídico antes de compartilhar a minuta.</p><Button variant="outline" className="w-full" onClick={() => window.location.assign("/copiloto")}>Consultar copiloto <MessageSquareMore className="size-4" /></Button></CardContent></Card></div></div>
  </section>;
}

function DiligenceWorkspace({ dealId, checklist, documents, analyses }: { dealId: number; checklist: Array<{ id: number; title: string; category: "federal" | "trabalhista" | "estadual" | "municipal" | "registral" | "imovel" | "outro"; issuer: string | null; status: "pendente" | "em_revisao" | "aprovado" | "dispensado"; attachedDocumentId: number | null; expiresAt: Date | string | null; notes: string | null }>; documents: Array<{ id: number; name: string; storageUrl: string; uploadedAt: Date | string }>; analyses: Array<{ id: number; documentId: number; status: "processando" | "concluida" | "falha" | "nao_suportado"; riskLevel: "baixo" | "moderado" | "alto" | "indeterminado"; summary: string | null; findings: Array<{ title: string; severity: "baixo" | "moderado" | "alto"; detail: string; recommendation: string }> | null; limitations: string | null; errorMessage: string | null }> }) {
  const utils = trpc.useUtils();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ title: "", category: "federal" as typeof checklist[number]["category"], issuer: "", notes: "", expiresAt: "" });
  const [uploadingItem, setUploadingItem] = useState<number | null>(null);
  const [analyzingItem, setAnalyzingItem] = useState<number | null>(null);
  const addItem = trpc.diligence.addItem.useMutation({ onSuccess: async () => { await utils.deals.get.invalidate({ dealId }); setOpen(false); setForm({ title: "", category: "federal", issuer: "", notes: "", expiresAt: "" }); toast.success("Item adicionado ao checklist de diligência."); }, onError: error => toast.error(error.message) });
  const updateStatus = trpc.diligence.updateStatus.useMutation({ onSuccess: () => utils.deals.get.invalidate({ dealId }), onError: error => toast.error(error.message) });
  const analyze = trpc.diligence.analyze.useMutation({ onSuccess: async result => { await utils.deals.get.invalidate({ dealId }); setAnalyzingItem(null); if (result.status === "concluida") toast.success("Leitura assistida da certidão concluída."); else if (result.status === "nao_suportado") toast.message("O arquivo foi anexado, mas não possui formato compatível para leitura por IA."); else toast.error("A certidão foi anexada, mas a análise assistida não pôde ser concluída."); }, onError: error => { setAnalyzingItem(null); toast.error(error.message); } });
  const attach = trpc.diligence.attach.useMutation({ onSuccess: async result => { await utils.deals.get.invalidate({ dealId }); setUploadingItem(null); setAnalyzingItem(result.itemId); toast.success("Certidão anexada. A leitura assistida foi iniciada."); analyze.mutate({ dealId, itemId: result.itemId, documentId: result.documentId }); }, onError: error => { setUploadingItem(null); toast.error(error.message); } });
  const uploadFile = (itemId: number, file?: File) => { if (!file) return; const reader = new FileReader(); setUploadingItem(itemId); reader.onload = () => attach.mutate({ dealId, itemId, fileName: file.name, mimeType: file.type || "application/octet-stream", dataUrl: String(reader.result) }); reader.onerror = () => { setUploadingItem(null); toast.error("Não foi possível ler o arquivo selecionado."); }; reader.readAsDataURL(file); };
  const approved = checklist.filter(item => item.status === "aprovado" || item.status === "dispensado").length;
  const progress = checklist.length ? Math.round(approved / checklist.length * 100) : 0;
  return <section><div className="mb-5 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p className="section-kicker">Dossiê documental</p><h2 className="font-display text-2xl font-semibold tracking-tight">Due diligence</h2><p className="mt-1 text-sm text-muted-foreground">Cada certidão anexada aparece automaticamente no dossiê disponibilizado ao cliente.</p></div><Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button><Plus className="size-4" /> Adicionar certidão</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle className="font-display text-2xl">Novo item de diligência</DialogTitle><DialogDescription>Defina o documento que precisa ser emitido ou conferido neste negócio.</DialogDescription></DialogHeader><div className="grid gap-4 py-3"><div className="grid gap-2"><Label>Certidão ou documento</Label><Input value={form.title} onChange={event => setForm(current => ({ ...current, title: event.target.value }))} placeholder="Ex.: Certidão de matrícula atualizada" /></div><div className="grid gap-2"><Label>Categoria</Label><select value={form.category} onChange={event => setForm(current => ({ ...current, category: event.target.value as typeof form.category }))} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="federal">Federal</option><option value="trabalhista">Trabalhista</option><option value="estadual">Estadual</option><option value="municipal">Municipal</option><option value="registral">Registral</option><option value="imovel">Imóvel</option><option value="outro">Outro</option></select></div><div className="grid gap-2"><Label>Órgão emissor</Label><Input value={form.issuer} onChange={event => setForm(current => ({ ...current, issuer: event.target.value }))} placeholder="Opcional" /></div><div className="grid gap-2"><Label>Validade</Label><Input type="date" value={form.expiresAt} onChange={event => setForm(current => ({ ...current, expiresAt: event.target.value }))} /></div><div className="grid gap-2"><Label>Observações</Label><Textarea value={form.notes} onChange={event => setForm(current => ({ ...current, notes: event.target.value }))} placeholder="Opcional" /></div></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={!form.title.trim() || addItem.isPending} onClick={() => addItem.mutate({ dealId, title: form.title, category: form.category, issuer: form.issuer || undefined, notes: form.notes || undefined, expiresAt: form.expiresAt ? new Date(`${form.expiresAt}T12:00:00`).toISOString() : null })}>{addItem.isPending ? <Loader2 className="size-4 animate-spin" /> : <Plus className="size-4" />} Adicionar</Button></DialogFooter></DialogContent></Dialog></div>
    <div className="mb-5 grid gap-4 md:grid-cols-3"><MetricCard icon={ClipboardCheck} label="Prontidão do processo" value={`${progress}%`} helper={`${approved}/${checklist.length} itens concluídos`} accent="bg-emerald-500" /><MetricCard icon={Scale} label="Itens em revisão" value={checklist.filter(item => item.status === "em_revisao").length} helper="Documentos que exigem conferência" accent="bg-amber-500" /><MetricCard icon={FileCheck2} label="Evidências indexadas" value={documents.length} helper="Documentos vinculados ao processo" accent="bg-violet-500" /></div>
    {checklist.length ? <div className="grid gap-3">{checklist.map(item => { const document = documents.find(doc => doc.id === item.attachedDocumentId); const analysis = document ? analyses.find(itemAnalysis => itemAnalysis.documentId === document.id) : undefined; const riskTone = analysis?.riskLevel === "alto" ? "border-red-200 bg-red-50 text-red-900" : analysis?.riskLevel === "moderado" ? "border-amber-200 bg-amber-50 text-amber-900" : "border-emerald-200 bg-emerald-50 text-emerald-900"; return <Card key={item.id} className="border-border/80"><CardContent className="p-5"><div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><Badge variant="outline" className="capitalize">{item.category}</Badge><span className={`text-xs font-medium ${item.status === "aprovado" ? "text-emerald-700" : item.status === "em_revisao" ? "text-amber-700" : "text-muted-foreground"}`}>{item.status.replaceAll("_", " ")}</span></div><h3 className="mt-3 font-display text-lg font-semibold tracking-tight">{item.title}</h3><p className="mt-1 text-sm text-muted-foreground">{item.issuer ?? "Órgão emissor não informado"}{item.expiresAt ? ` · Validade: ${formatDate(item.expiresAt)}` : ""}</p>{document ? <a href={document.storageUrl} target="_blank" rel="noreferrer" className="mt-3 inline-flex items-center gap-2 text-sm font-medium underline underline-offset-4"><FileCheck2 className="size-4" /> {document.name}</a> : null}</div><div className="flex flex-wrap gap-2"><select value={item.status} onChange={event => updateStatus.mutate({ dealId, itemId: item.id, status: event.target.value as "pendente" | "em_revisao" | "aprovado" | "dispensado" })} className="h-9 rounded-md border bg-background px-3 text-sm"><option value="pendente">Pendente</option><option value="em_revisao">Em revisão</option><option value="aprovado">Aprovado</option><option value="dispensado">Dispensado</option></select>{document ? <Button variant="outline" disabled={analyzingItem === item.id || analyze.isPending} onClick={() => { setAnalyzingItem(item.id); analyze.mutate({ dealId, itemId: item.id, documentId: document.id }); }}><Sparkles className="size-4" /> {analyzingItem === item.id ? "Lendo..." : "Analisar com IA"}</Button> : null}<Button variant="outline" asChild><label><UploadCloud className="size-4" /> {uploadingItem === item.id ? "Enviando..." : document ? "Substituir anexo" : "Anexar certidão"}<input className="hidden" type="file" accept="application/pdf,image/*,.doc,.docx" disabled={uploadingItem === item.id} onChange={event => uploadFile(item.id, event.target.files?.[0])} /></label></Button></div></div>{analysis ? <div className={`mt-5 rounded-xl border p-4 ${riskTone}`}><div className="flex items-start gap-3"><TriangleAlert className="mt-0.5 size-4 shrink-0" /><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-semibold">Leitura assistida · risco {analysis.riskLevel}</p>{analysis.status === "processando" ? <span className="text-xs">Em processamento</span> : null}</div>{analysis.summary ? <p className="mt-2 text-sm leading-6">{analysis.summary}</p> : null}{analysis.findings?.length ? <div className="mt-3 space-y-2">{analysis.findings.map((finding, index) => <div key={`${finding.title}-${index}`} className="rounded-lg bg-white/60 p-3"><p className="text-sm font-semibold">{finding.title} <span className="font-normal">· {finding.severity}</span></p><p className="mt-1 text-sm leading-5">{finding.detail}</p><p className="mt-2 text-xs font-medium">Próximo passo: {finding.recommendation}</p></div>)}</div> : null}{analysis.limitations ? <p className="mt-3 text-xs leading-5 opacity-80">Limitações da leitura: {analysis.limitations}</p> : null}{analysis.errorMessage ? <p className="mt-3 text-xs">{analysis.errorMessage}</p> : null}</div></div></div> : null}</CardContent></Card>; })}</div> : <EmptyState icon={ClipboardCheck} title="Checklist de diligência ainda vazio" description="Inclua as certidões exigidas por esta operação. Não há lista fixa, pois a documentação depende do contexto real do negócio." action={<Button onClick={() => setOpen(true)}><Plus className="size-4" /> Adicionar primeiro item</Button>} />}
  </section>;
}

function ClientPanelShare({ deal, documents }: { deal: { clientToken: string; title: string; stage: DealStage }; documents: Array<{ id: number; name: string; storageUrl: string; uploadedAt: Date | string }> }) {
  return <section className="grid gap-6 xl:grid-cols-[minmax(0,1fr)_350px]"><Card className="border-border/80"><CardHeader><p className="section-kicker">Compartilhamento externo</p><CardTitle className="font-display text-2xl tracking-tight">Painel do cliente</CardTitle><CardDescription>Envie um único link para o cliente consultar o status do processo, os documentos liberados e a versão contratual atual.</CardDescription></CardHeader><CardContent>{documents.length ? <div className="overflow-hidden rounded-lg border"><div className="grid grid-cols-[1fr_auto] gap-3 border-b bg-muted/30 px-4 py-3 text-xs font-semibold text-muted-foreground"><span>Documento no dossiê</span><span>Enviado em</span></div>{documents.map(document => <a key={document.id} href={document.storageUrl} target="_blank" rel="noreferrer" className="grid grid-cols-[1fr_auto] gap-3 border-b px-4 py-4 text-sm transition hover:bg-muted/30 last:border-0"><span className="flex items-center gap-2 font-medium"><FileText className="size-4 text-muted-foreground" />{document.name}</span><span className="text-muted-foreground">{formatDate(document.uploadedAt)}</span></a>)}</div> : <div className="rounded-lg border border-dashed px-4 py-9 text-center text-sm text-muted-foreground">Os documentos anexados à due diligence serão listados aqui antes do compartilhamento.</div>}</CardContent></Card><Card className="border-0 bg-[#19171d] text-white"><CardContent className="p-6"><div className="flex size-10 items-center justify-center rounded-xl bg-amber-300/10 text-amber-300"><Link2 className="size-5" /></div><p className="mt-6 text-[10px] font-bold uppercase tracking-[0.16em] text-zinc-400">Acesso do cliente</p><h2 className="mt-2 font-display text-2xl font-semibold tracking-tight">Um link seguro para acompanhar o processo.</h2><p className="mt-3 text-sm leading-6 text-zinc-300">O endereço é exclusivo deste negócio e se mantém até o encerramento do processo.</p><Button className="mt-7 w-full bg-white text-zinc-900 hover:bg-zinc-100" onClick={() => copyShareLink(`/cliente/${deal.clientToken}`, "Link do painel do cliente")}><Copy className="size-4" /> Copiar link do cliente</Button><p className="mt-4 text-xs leading-5 text-zinc-400">Etapa visível ao cliente: {stageMeta[deal.stage].label}.</p></CardContent></Card></section>;
}

export function CopilotPage() {
  type CopilotAgent = "venda" | "locacao" | "diligencia" | "comparador";
  const [agent, setAgent] = useState<CopilotAgent>("venda");
  const [sessionId] = useState(() => typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `session-${Date.now()}`);
  const [messages, setMessages] = useState<Message[]>([]);
  const sources = trpc.library.list.useQuery();
  const agentOptions: Array<{ id: CopilotAgent; title: string; description: string }> = [
    { id: "venda", title: "Compra e venda", description: "Contratos e estrutura da operação." },
    { id: "locacao", title: "Locação", description: "Garantias e relações locatícias." },
    { id: "diligencia", title: "Due diligence", description: "Riscos e evidências documentais." },
    { id: "comparador", title: "Comparador de minutas", description: "Diferenças entre duas versões contratuais." },
  ];
  const agentCopy = agentOptions.find(item => item.id === agent) ?? agentOptions[0];
  const ask = trpc.copiloto.chat.useMutation({ onSuccess: result => setMessages(current => [...current, { role: "assistant", content: result.content }]), onError: error => { toast.error(error.message); setMessages(current => [...current, { role: "assistant", content: "Não foi possível concluir a orientação agora. Revise sua conexão e tente novamente." }]); } });
  const send = (content: string) => { setMessages(current => [...current, { role: "user", content }]); ask.mutate({ agent, sessionId, message: content }); };
  const receiveComparison = (content: string) => setMessages(current => [...current, { role: "user", content: "Comparei as duas minutas selecionadas." }, { role: "assistant", content }]);
  return <DashboardLayout><div className="page-shell"><PageHeader eyebrow="IA jurídica assistida" title="Copiloto Jurídico" description="Consulte agentes especializados, anexe minutas para análise assistida e compare versões contratuais com rastreabilidade e revisão humana." actions={<Button variant="outline" onClick={() => window.location.assign("/configuracoes")}>Gerenciar biblioteca <BookOpenText className="size-4" /></Button>} />
    <div className="grid gap-6 xl:grid-cols-[260px_minmax(0,1fr)] 2xl:grid-cols-[260px_minmax(0,1fr)_330px]"><aside className="space-y-3"><p className="section-kicker px-1">Especialidade</p>{agentOptions.map(item => <button key={item.id} onClick={() => { setAgent(item.id); setMessages([]); }} className={`w-full rounded-xl border p-4 text-left transition ${agent === item.id ? "border-foreground bg-foreground text-background" : "border-border/80 bg-card hover:border-foreground/25"}`}><div className="flex items-center justify-between"><Scale className="size-4" /><ChevronRight className="size-4" /></div><p className="mt-5 font-display text-lg font-semibold tracking-tight">{item.title}</p><p className={`mt-1 text-xs leading-5 ${agent === item.id ? "text-zinc-300" : "text-muted-foreground"}`}>{item.description}</p></button>)}<Card className="border-border/80 bg-muted/30"><CardContent className="p-4"><p className="text-sm font-semibold">Fontes configuradas</p><p className="mt-1 text-sm leading-5 text-muted-foreground">{sources.data?.length ? `${sources.data.length} fonte${sources.data.length === 1 ? "" : "s"} ativa${sources.data.length === 1 ? "" : "s"} na biblioteca jurídica.` : "Nenhuma fonte foi cadastrada ainda."}</p></CardContent></Card></aside><section><div className="mb-3 rounded-xl border border-violet-200 bg-violet-50/80 px-4 py-3"><p className="font-display text-lg font-semibold tracking-tight text-violet-950">Agente de {agentCopy.title}</p><p className="mt-1 text-sm text-violet-800">{agent === "comparador" ? "Selecione duas minutas no painel ao lado para receber uma comparação estruturada de diferenças e pontos de atenção." : "Os anexos desta conversa são considerados como contexto junto à biblioteca jurídica configurada."} O copiloto sinaliza premissas e não substitui a revisão do profissional responsável.</p></div><AIChatBox messages={messages} onSendMessage={send} isLoading={ask.isPending} height="calc(100vh - 300px)" placeholder={agent === "comparador" ? "Faça uma pergunta sobre as minutas anexadas..." : "Descreva o caso ou envie a dúvida jurídica..."} emptyStateMessage={agent === "comparador" ? "Anexe e selecione duas minutas para comparar." : "Como o agente pode ajudar nesta operação?"} suggestedPrompts={agent === "comparador" ? ["Quais diferenças alteram o risco comercial?", "Quais cláusulas exigem revisão prioritária?"] : ["Quais informações devo validar antes de elaborar a minuta?", "Quais são os principais riscos deste tipo de operação?", "Como estruturar uma checklist de revisão para este contrato?"]} /></section><aside className="xl:col-span-2 2xl:col-span-1"><CopilotAttachmentsPanel sessionId={sessionId} agent={agent} onComparison={receiveComparison} /></aside></div>
  </div></DashboardLayout>;
}

export function ObligationsPage() {
  const deals = trpc.deals.list.useQuery();
  const list = trpc.obligations.list.useQuery();
  const utils = trpc.useUtils();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ dealId: "", title: "", description: "", dueAt: "", alertDaysBefore: "3" });
  const create = trpc.obligations.create.useMutation({ onSuccess: async () => { await Promise.all([utils.obligations.list.invalidate(), utils.dashboard.get.invalidate()]); setOpen(false); setForm({ dealId: "", title: "", description: "", dueAt: "", alertDaysBefore: "3" }); toast.success("Obrigação registrada e vinculada ao negócio."); }, onError: error => toast.error(error.message) });
  const complete = trpc.obligations.complete.useMutation({ onSuccess: () => { utils.obligations.list.invalidate(); utils.dashboard.get.invalidate(); toast.success("Obrigação marcada como concluída."); }, onError: error => toast.error(error.message) });
  return <DashboardLayout><div className="page-shell"><PageHeader eyebrow="Agenda operacional" title="Obrigações e prazos" description="Registre pendências vinculadas aos negócios e mantenha a operação em dia com avisos configuráveis de proximidade." actions={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button disabled={!deals.data?.length} title={!deals.data?.length ? "Crie um negócio antes de registrar uma obrigação" : undefined}><Plus className="size-4" /> Criar obrigação</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle className="font-display text-2xl">Nova obrigação</DialogTitle><DialogDescription>Toda obrigação é vinculada a um negócio para preservar o histórico do processo.</DialogDescription></DialogHeader><div className="grid gap-4 py-3"><div className="grid gap-2"><Label>Negócio</Label><select value={form.dealId} onChange={event => setForm(current => ({ ...current, dealId: event.target.value }))} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="">Selecione o negócio</option>{deals.data?.map(deal => <option key={deal.id} value={deal.id}>{deal.title}</option>)}</select></div><div className="grid gap-2"><Label>Obrigação</Label><Input value={form.title} onChange={event => setForm(current => ({ ...current, title: event.target.value }))} placeholder="Ex.: Conferir versão final da minuta" /></div><div className="grid gap-2"><Label>Descrição</Label><Textarea value={form.description} onChange={event => setForm(current => ({ ...current, description: event.target.value }))} placeholder="Opcional" /></div><div className="grid grid-cols-2 gap-4"><div className="grid gap-2"><Label>Prazo</Label><Input type="date" value={form.dueAt} onChange={event => setForm(current => ({ ...current, dueAt: event.target.value }))} /></div><div className="grid gap-2"><Label>Alertar com antecedência</Label><Input type="number" min="0" max="30" value={form.alertDaysBefore} onChange={event => setForm(current => ({ ...current, alertDaysBefore: event.target.value }))} /></div></div></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={!form.dealId || !form.title.trim() || !form.dueAt || create.isPending} onClick={() => create.mutate({ dealId: Number(form.dealId), title: form.title, description: form.description || undefined, dueAt: new Date(`${form.dueAt}T12:00:00`).toISOString(), alertDaysBefore: Number(form.alertDaysBefore) })}>{create.isPending ? <Loader2 className="size-4 animate-spin" /> : <Plus className="size-4" />} Criar obrigação</Button></DialogFooter></DialogContent></Dialog>} />
    {!deals.data?.length ? <div className="mb-5 rounded-xl border border-amber-200 bg-amber-50 px-5 py-4 text-sm text-amber-900"><strong>Vínculo obrigatório.</strong> Para registrar obrigações, primeiro crie um negócio ou receba um intake. Assim, cada pendência permanece associada ao processo correto.</div> : null}
    {list.isLoading ? <div className="h-28 animate-pulse rounded-xl bg-muted" /> : list.data?.length ? <div className="space-y-3">{list.data.map(({ obligation, deal }) => <Card key={obligation.id} className="border-border/80"><CardContent className="flex flex-col gap-4 p-5 md:flex-row md:items-center md:justify-between"><div className="flex gap-4"><div className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-muted"><CalendarClock className="size-5" /></div><div><h3 className="font-display text-lg font-semibold tracking-tight">{obligation.title}</h3><p className="mt-1 text-sm text-muted-foreground">{deal.title} · Vence {formatDate(obligation.dueAt)}</p>{obligation.description ? <p className="mt-2 text-sm text-muted-foreground">{obligation.description}</p> : null}</div></div><div className="flex items-center gap-3"><Badge variant="outline" className={obligation.status === "concluida" ? "border-emerald-200 bg-emerald-50 text-emerald-800" : ""}>{obligation.status}</Badge>{obligation.status !== "concluida" ? <Button variant="outline" size="sm" disabled={complete.isPending} onClick={() => complete.mutate({ id: obligation.id })}><Check className="size-4" /> Concluir</Button> : null}</div></CardContent></Card>)}</div> : <EmptyState icon={CalendarClock} title="Nenhuma obrigação cadastrada" description="As obrigações permitem acompanhar prazos reais de cada negócio sem perder o vínculo com os contratos e as partes." action={deals.data?.length ? <Button onClick={() => setOpen(true)}><Plus className="size-4" /> Criar primeira obrigação</Button> : undefined} />}
  </div></DashboardLayout>;
}

export function ArchivePage() {
  const [, setLocation] = useLocation();
  const archive = trpc.deals.list.useQuery({ archived: true });
  const deals = archive.data ?? [];
  const vgv = deals.reduce((total, deal) => total + (deal.estimatedValue ?? 0), 0);
  return <DashboardLayout><div className="page-shell"><PageHeader eyebrow="Encerramento e histórico" title="Arquivo" description="Consulte processos finalizados, seus valores registrados e o histórico documental preservado após o encerramento." actions={<div className="inline-flex items-center gap-2 text-sm text-muted-foreground"><LockKeyhole className="size-4" /> Arquivamento auditável</div>} /><div className="grid gap-4 md:grid-cols-3"><MetricCard icon={FolderArchive} label="Negócios fechados" value={deals.length} helper="Processos arquivados" /><MetricCard icon={BriefcaseBusiness} label="VGV" value={formatMoney(vgv)} helper="Valor geral registrado" accent="bg-emerald-500" /><MetricCard icon={FileCheck2} label="Dossiês preservados" value="Seguro" helper="Documentos vinculados aos processos" accent="bg-violet-500" /></div><div className="mt-7">{archive.isLoading ? <div className="h-32 animate-pulse rounded-xl bg-muted" /> : deals.length ? <div className="overflow-hidden rounded-xl border border-border/80 bg-card">{deals.map(deal => <button key={deal.id} onClick={() => setLocation(`/negocios/${deal.id}`)} className="flex w-full items-center justify-between gap-4 border-b px-5 py-4 text-left transition hover:bg-muted/30 last:border-0"><div><p className="font-display text-lg font-semibold tracking-tight">{deal.title}</p><p className="mt-1 text-sm text-muted-foreground">{deal.code} · Arquivado em {formatDate(deal.archivedAt)}</p></div><div className="flex items-center gap-4"><span className="text-sm font-medium">{formatMoney(deal.estimatedValue)}</span><ChevronRight className="size-4 text-muted-foreground" /></div></button>)}</div> : <EmptyState icon={Archive} title="O arquivo ainda está vazio" description="Quando um negócio for finalizado, você poderá arquivá-lo preservando seu histórico e seus documentos para consulta futura." />}</div></div></DashboardLayout>;
}

function WordTemplateDialog() {
  const utils = trpc.useUtils();
  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [contractType, setContractType] = useState("Contrato de compra e venda");
  const [transactionType, setTransactionType] = useState<TransactionType>("venda");
  const [file, setFile] = useState<{ name: string; mimeType: string; dataUrl: string } | null>(null);
  const create = trpc.templates.create.useMutation({
    onSuccess: async () => {
      await utils.templates.list.invalidate();
      setOpen(false);
      setName("");
      setContractType("Contrato de compra e venda");
      setFile(null);
      toast.success("Modelo Word anexado e preparado para edição.");
    },
    onError: error => toast.error(error.message),
  });
  const selectFile = (selected?: File) => {
    if (!selected) return;
    if (!selected.name.toLowerCase().endsWith(".docx") || selected.size > 10 * 1024 * 1024) {
      toast.error("Envie um arquivo DOCX de até 10 MB.");
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      setFile({ name: selected.name, mimeType: selected.type || "application/vnd.openxmlformats-officedocument.wordprocessingml.document", dataUrl: String(reader.result) });
      if (!name.trim()) setName(selected.name.replace(/\.docx$/i, ""));
    };
    reader.onerror = () => toast.error("Não foi possível ler o arquivo Word selecionado.");
    reader.readAsDataURL(selected);
  };
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button variant="outline"><UploadCloud className="size-4" /> Anexar Word</Button></DialogTrigger><DialogContent className="sm:max-w-lg"><DialogHeader><DialogTitle className="font-display text-2xl">Anexar modelo Word</DialogTitle><DialogDescription>Envie um arquivo DOCX de até 10 MB. O documento original é preservado e seu conteúdo é convertido em uma minuta editável.</DialogDescription></DialogHeader><div className="grid gap-4 py-3"><div className="grid gap-2"><Label>Nome do modelo</Label><Input value={name} onChange={event => setName(event.target.value)} placeholder="Ex.: Compra e venda com financiamento" /></div><div className="grid gap-2"><Label>Tipo de contrato</Label><Input value={contractType} onChange={event => setContractType(event.target.value)} placeholder="Ex.: Contrato de compra e venda" /></div><div className="grid gap-2"><Label>Tipo de operação</Label><select value={transactionType} onChange={event => setTransactionType(event.target.value as TransactionType)} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="venda">Compra e venda</option><option value="locacao">Locação</option><option value="outro">Outra operação</option></select></div><div className="grid gap-2"><Label>Arquivo DOCX</Label><label className="flex cursor-pointer items-center justify-between rounded-lg border border-dashed border-border p-4 text-sm transition hover:bg-muted/40"><span className="flex min-w-0 items-center gap-2"><FileText className="size-4 shrink-0" /><span className="truncate">{file?.name ?? "Selecionar arquivo Word"}</span></span><span className="shrink-0 text-xs text-muted-foreground">até 10 MB</span><input className="hidden" type="file" accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document" onChange={event => selectFile(event.target.files?.[0])} /></label>{file ? <button className="w-fit text-xs font-semibold underline underline-offset-4" onClick={() => setFile(null)}>Remover arquivo</button> : null}</div></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={!name.trim() || !contractType.trim() || !file || create.isPending} onClick={() => file && create.mutate({ name, contractType, transactionType, content: undefined, fields: [], sourceFileName: file.name, sourceFileMimeType: file.mimeType, sourceFileDataUrl: file.dataUrl })}>{create.isPending ? <Loader2 className="size-4 animate-spin" /> : <UploadCloud className="size-4" />} Anexar como modelo</Button></DialogFooter></DialogContent></Dialog>;
}

function WordTemplateSourceIndex({ templates }: { templates: Array<{ id: number; name: string; sourceFileName: string | null; sourceFileUrl: string | null }> }) {
  const attached = templates.filter(template => template.sourceFileUrl);
  if (!attached.length) return null;
  return <Card className="mb-6 border-violet-200 bg-violet-50/45"><CardContent className="flex flex-col gap-4 p-4 md:flex-row md:items-center md:justify-between"><div><p className="section-kicker text-violet-700">Modelos Word anexados</p><p className="mt-1 text-sm leading-6 text-violet-950">Os arquivos originais permanecem disponíveis e o texto extraído pode ser selecionado no elaborador de contratos.</p></div><div className="flex flex-wrap gap-2">{attached.map(template => <a key={template.id} href={template.sourceFileUrl ?? undefined} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-md border border-violet-200 bg-white px-3 py-2 text-sm font-semibold text-violet-950 transition hover:bg-violet-100"><FileText className="size-4" />{template.sourceFileName ?? template.name}</a>)}</div></CardContent></Card>;
}

export function SettingsPage() {
  const [section, setSection] = useState<"templates" | "kits" | "library" | "access" | "alerts" | "integrations">("templates");
  const templates = trpc.templates.list.useQuery();
  const library = trpc.library.list.useQuery();
  const alertSetting = trpc.settings.getAlerts.useQuery();
  const accessSetting = trpc.settings.getAccesses.useQuery();
  const integrationSetting = trpc.settings.getIntegrations.useQuery();
  const utils = trpc.useUtils();
  const [templateOpen, setTemplateOpen] = useState(false);
  const [libraryOpen, setLibraryOpen] = useState(false);
  const [templateForm, setTemplateForm] = useState({ name: "", contractType: "Contrato de compra e venda", transactionType: "venda" as TransactionType, fields: "", content: "" });
  const [libraryForm, setLibraryForm] = useState({ title: "", category: "legislacao" as "legislacao" | "jurisprudencia" | "clausula" | "procedimento" | "nota", content: "" });
  const [alerts, setAlerts] = useState({ enabled: true, daysBefore: 3 });
  const [members, setMembers] = useState<Array<{ name: string; email: string; role: "administrador" | "operador" | "leitor" }>>([]);
  const [integrations, setIntegrations] = useState<Array<{ name: string; category: "assinatura" | "certidoes" | "conector"; enabled: boolean }>>([]);
  useEffect(() => { const value = alertSetting.data?.value as { enabled?: boolean; daysBefore?: number } | undefined; if (value) setAlerts({ enabled: value.enabled ?? true, daysBefore: value.daysBefore ?? 3 }); }, [alertSetting.data?.id]);
  useEffect(() => { const value = accessSetting.data?.value as { members?: Array<{ name: string; email: string; role: "administrador" | "operador" | "leitor" }> } | undefined; if (value?.members) setMembers(value.members); }, [accessSetting.data?.id]);
  useEffect(() => { const value = integrationSetting.data?.value as { integrations?: Array<{ name: string; category: "assinatura" | "certidoes" | "conector"; enabled: boolean }> } | undefined; if (value?.integrations) setIntegrations(value.integrations); }, [integrationSetting.data?.id]);
  const createTemplate = trpc.templates.create.useMutation({ onSuccess: async () => { await templates.refetch(); setTemplateOpen(false); setTemplateForm({ name: "", contractType: "Contrato de compra e venda", transactionType: "venda", fields: "", content: "" }); toast.success("Modelo contratual cadastrado."); }, onError: error => toast.error(error.message) });
  const createLibrary = trpc.library.create.useMutation({ onSuccess: async () => { await library.refetch(); setLibraryOpen(false); setLibraryForm({ title: "", category: "legislacao", content: "" }); toast.success("Fonte adicionada à biblioteca jurídica."); }, onError: error => toast.error(error.message) });
  const saveAlerts = trpc.settings.saveAlerts.useMutation({ onSuccess: () => { utils.settings.getAlerts.invalidate(); toast.success("Preferências de alerta atualizadas."); }, onError: error => toast.error(error.message) });
  const saveAccesses = trpc.settings.saveAccesses.useMutation({ onSuccess: () => { utils.settings.getAccesses.invalidate(); toast.success("Matriz de acessos atualizada."); }, onError: error => toast.error(error.message) });
  const saveIntegrations = trpc.settings.saveIntegrations.useMutation({ onSuccess: () => { utils.settings.getIntegrations.invalidate(); toast.success("Configuração de integrações atualizada."); }, onError: error => toast.error(error.message) });
  const nav = [{ id: "templates", icon: FileText, title: "Modelos de contrato", description: "Arquivos-base e campos editáveis" }, { id: "kits", icon: ClipboardCheck, title: "Kits de diligência", description: "Checklists reutilizáveis por operação" }, { id: "library", icon: BookOpenText, title: "Biblioteca jurídica", description: "Fontes para o Copiloto Jurídico" }, { id: "access", icon: UsersRound, title: "Acessos", description: "Papéis e responsabilidades" }, { id: "alerts", icon: BellRing, title: "Alertas", description: "Prazos e comunicações operacionais" }, { id: "integrations", icon: Settings2, title: "Integrações", description: "Assinatura, certidões e conectores" }] as const;
  return <DashboardLayout><div className="page-shell"><PageHeader title="Configurações" description="Estruture os modelos, fontes jurídicas, regras operacionais e integrações que sustentam a atuação da equipe." actions={<><WordTemplateDialog /><div className="inline-flex items-center gap-2 rounded-lg border bg-card px-3 py-2 text-xs text-muted-foreground"><ShieldCheck className="size-4 text-emerald-600" /> Dados preservados por negócio</div></>} />
    <WordTemplateSourceIndex templates={templates.data ?? []} />
    <div className="grid gap-8 lg:grid-cols-[250px_minmax(0,1fr)]"><aside className="space-y-1">{nav.map(item => <button key={item.id} onClick={() => setSection(item.id)} className={`flex w-full items-start gap-3 rounded-lg p-3 text-left transition ${section === item.id ? "bg-foreground text-background" : "hover:bg-muted"}`}><item.icon className="mt-0.5 size-4 shrink-0" /><span><span className="block text-sm font-semibold">{item.title}</span><span className={`mt-1 block text-xs leading-5 ${section === item.id ? "text-zinc-300" : "text-muted-foreground"}`}>{item.description}</span></span></button>)}</aside><section>{section === "templates" ? <div><div className="flex flex-col justify-between gap-4 border-b pb-5 sm:flex-row sm:items-end"><div><p className="section-kicker">Preparação de minuta</p><h2 className="font-display text-2xl font-semibold tracking-tight">Arquivos-base selecionáveis</h2><p className="mt-1 text-sm text-muted-foreground">Cadastre modelos utilizados para cada operação. Eles permanecem editáveis antes do envio.</p></div><Dialog open={templateOpen} onOpenChange={setTemplateOpen}><DialogTrigger asChild><Button><Plus className="size-4" /> Adicionar modelo</Button></DialogTrigger><DialogContent className="sm:max-w-2xl"><DialogHeader><DialogTitle className="font-display text-2xl">Novo modelo contratual</DialogTitle><DialogDescription>Use marcadores como <code>{"{{NEGOCIO}}"}</code> e <code>{"{{IMOVEL}}"}</code> no conteúdo para preencher o contexto do negócio.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><div className="grid gap-2"><Label>Nome do modelo</Label><Input value={templateForm.name} onChange={event => setTemplateForm(current => ({ ...current, name: event.target.value }))} placeholder="Ex.: Compra e venda à vista" /></div><div className="grid gap-2"><Label>Tipo de contrato</Label><Input value={templateForm.contractType} onChange={event => setTemplateForm(current => ({ ...current, contractType: event.target.value }))} placeholder="Ex.: Contrato de compra e venda" /></div><div className="grid gap-2"><Label>Tipo de operação</Label><select value={templateForm.transactionType} onChange={event => setTemplateForm(current => ({ ...current, transactionType: event.target.value as TransactionType }))} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="venda">Compra e venda</option><option value="locacao">Locação</option><option value="outro">Outra operação</option></select></div><div className="grid gap-2"><Label>Campos mapeados</Label><Input value={templateForm.fields} onChange={event => setTemplateForm(current => ({ ...current, fields: event.target.value }))} placeholder="Ex.: QUALIFICACAO_COMPRADOR, PRECO, FORMA_PAGAMENTO" /></div><div className="grid gap-2"><Label>Conteúdo da minuta</Label><Textarea value={templateForm.content} onChange={event => setTemplateForm(current => ({ ...current, content: event.target.value }))} className="min-h-64 font-mono text-xs leading-6" placeholder="Cole ou redija aqui o conteúdo do seu modelo..." /></div></div><DialogFooter><Button variant="outline" onClick={() => setTemplateOpen(false)}>Cancelar</Button><Button disabled={!templateForm.name || !templateForm.contractType || templateForm.content.length < 20 || createTemplate.isPending} onClick={() => createTemplate.mutate({ name: templateForm.name, contractType: templateForm.contractType, transactionType: templateForm.transactionType, content: templateForm.content, fields: templateForm.fields.split(",").map(value => value.trim()).filter(Boolean) })}>{createTemplate.isPending ? <Loader2 className="size-4 animate-spin" /> : <Plus className="size-4" />} Salvar modelo</Button></DialogFooter></DialogContent></Dialog></div>{templates.data?.length ? <div className="mt-5 grid gap-4 md:grid-cols-2">{templates.data.map(template => <Card key={template.id} className="border-border/80"><CardContent className="p-5"><div className="flex items-center justify-between"><div className="flex size-10 items-center justify-center rounded-lg bg-muted"><FileText className="size-5" /></div><Badge variant="outline">v{template.version}</Badge></div><h3 className="mt-5 font-display text-lg font-semibold tracking-tight">{template.name}</h3><p className="mt-1 text-sm text-muted-foreground">{template.contractType} · {template.transactionType === "venda" ? "Compra e venda" : template.transactionType === "locacao" ? "Locação" : "Outra operação"} · {Array.isArray(template.fields) ? template.fields.length : 0} campos mapeados</p></CardContent></Card>)}</div> : <div className="mt-5"><EmptyState icon={FileText} title="Nenhum modelo contratual cadastrado" description="Adicione seus próprios arquivos-base para que o elaborador de contratos gere minutas a partir da estrutura jurídica da sua operação." action={<Button onClick={() => setTemplateOpen(true)}><Plus className="size-4" /> Cadastrar modelo</Button>} /></div>}</div> : null}
      {section === "kits" ? <DiligenceKitSettings /> : null}
      {section === "library" ? <div><div className="flex flex-col justify-between gap-4 border-b pb-5 sm:flex-row sm:items-end"><div><p className="section-kicker">Base de conhecimento</p><h2 className="font-display text-2xl font-semibold tracking-tight">Biblioteca jurídica</h2><p className="mt-1 text-sm text-muted-foreground">Fontes internas que orientam o Copiloto Jurídico para cada operação.</p></div><Dialog open={libraryOpen} onOpenChange={setLibraryOpen}><DialogTrigger asChild><Button><Plus className="size-4" /> Adicionar fonte</Button></DialogTrigger><DialogContent className="sm:max-w-2xl"><DialogHeader><DialogTitle className="font-display text-2xl">Nova fonte jurídica</DialogTitle><DialogDescription>Cadastre um texto de referência, procedimento, cláusula ou entendimento que poderá ser considerado pelo copiloto.</DialogDescription></DialogHeader><div className="grid gap-4 py-2"><div className="grid gap-2"><Label>Título</Label><Input value={libraryForm.title} onChange={event => setLibraryForm(current => ({ ...current, title: event.target.value }))} placeholder="Ex.: Procedimento interno de análise de matrícula" /></div><div className="grid gap-2"><Label>Categoria</Label><select value={libraryForm.category} onChange={event => setLibraryForm(current => ({ ...current, category: event.target.value as typeof libraryForm.category }))} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="legislacao">Legislação</option><option value="jurisprudencia">Jurisprudência</option><option value="clausula">Cláusula</option><option value="procedimento">Procedimento</option><option value="nota">Nota interna</option></select></div><div className="grid gap-2"><Label>Conteúdo</Label><Textarea value={libraryForm.content} onChange={event => setLibraryForm(current => ({ ...current, content: event.target.value }))} className="min-h-64" placeholder="Insira o conteúdo que deve servir de referência ao copiloto..." /></div></div><DialogFooter><Button variant="outline" onClick={() => setLibraryOpen(false)}>Cancelar</Button><Button disabled={!libraryForm.title || libraryForm.content.length < 20 || createLibrary.isPending} onClick={() => createLibrary.mutate(libraryForm)}>{createLibrary.isPending ? <Loader2 className="size-4 animate-spin" /> : <Plus className="size-4" />} Adicionar fonte</Button></DialogFooter></DialogContent></Dialog></div>{library.data?.length ? <div className="mt-5 space-y-3">{library.data.map(source => <Card key={source.id} className="border-border/80"><CardContent className="p-5"><div className="flex items-start justify-between gap-4"><div><Badge variant="outline" className="capitalize">{source.category}</Badge><h3 className="mt-3 font-display text-lg font-semibold tracking-tight">{source.title}</h3><p className="mt-2 line-clamp-3 text-sm leading-6 text-muted-foreground">{source.content}</p></div><BookOpenText className="size-5 shrink-0 text-muted-foreground" /></div></CardContent></Card>)}</div> : <div className="mt-5"><EmptyState icon={BookOpenText} title="Biblioteca jurídica vazia" description="O Copiloto Jurídico responderá com ressalvas até que você cadastre as fontes que representam sua base jurídica e seus procedimentos internos." action={<Button onClick={() => setLibraryOpen(true)}><Plus className="size-4" /> Adicionar primeira fonte</Button>} /></div>}</div> : null}
      {section === "access" ? <Card className="border-border/80"><CardHeader><p className="section-kicker">Governança de equipe</p><CardTitle className="font-display text-2xl tracking-tight">Acessos e papéis</CardTitle><CardDescription>Defina a matriz operacional da equipe. O ingresso no ambiente continua protegido pelo login da plataforma.</CardDescription></CardHeader><CardContent><div className="space-y-3">{members.map((member, index) => <div key={`${member.email}-${index}`} className="grid gap-3 rounded-lg border p-4 md:grid-cols-[1fr_1fr_150px_auto]"><Input value={member.name} onChange={event => setMembers(current => current.map((item, position) => position === index ? { ...item, name: event.target.value } : item))} placeholder="Nome" /><Input type="email" value={member.email} onChange={event => setMembers(current => current.map((item, position) => position === index ? { ...item, email: event.target.value } : item))} placeholder="E-mail" /><select value={member.role} onChange={event => setMembers(current => current.map((item, position) => position === index ? { ...item, role: event.target.value as typeof member.role } : item))} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="administrador">Administrador</option><option value="operador">Operador</option><option value="leitor">Leitor</option></select><Button variant="ghost" size="sm" onClick={() => setMembers(current => current.filter((_item, position) => position !== index))}>Remover</Button></div>)}{!members.length ? <div className="rounded-lg border border-dashed p-6 text-sm text-muted-foreground">Inclua os membros que podem operar, acompanhar ou administrar os processos jurídicos.</div> : null}<div className="flex flex-wrap gap-2 pt-2"><Button variant="outline" onClick={() => setMembers(current => [...current, { name: "", email: "", role: "operador" }])}><Plus className="size-4" /> Adicionar membro</Button><Button disabled={saveAccesses.isPending || members.some(member => !member.name.trim() || !member.email.trim())} onClick={() => saveAccesses.mutate({ members })}>{saveAccesses.isPending ? <Loader2 className="size-4 animate-spin" /> : <Check className="size-4" />} Salvar acessos</Button></div></div></CardContent></Card> : null}
      {section === "alerts" ? <Card className="border-border/80"><CardHeader><p className="section-kicker">Comunicação operacional</p><CardTitle className="font-display text-2xl tracking-tight">Alertas e prazos</CardTitle><CardDescription>Defina a antecedência padrão de aviso para as obrigações da operação.</CardDescription></CardHeader><CardContent className="max-w-xl space-y-5"><label className="flex items-center justify-between rounded-lg border p-4"><span><strong className="block text-sm">Alertas de prazos</strong><span className="mt-1 block text-sm text-muted-foreground">Registrar preferências para lembretes operacionais.</span></span><input type="checkbox" checked={alerts.enabled} onChange={event => setAlerts(current => ({ ...current, enabled: event.target.checked }))} className="size-4 accent-black" /></label><div className="grid gap-2"><Label>Antecedência padrão (dias)</Label><Input type="number" min="0" max="30" value={alerts.daysBefore} onChange={event => setAlerts(current => ({ ...current, daysBefore: Number(event.target.value) }))} /></div><Button disabled={saveAlerts.isPending} onClick={() => saveAlerts.mutate(alerts)}>{saveAlerts.isPending ? <Loader2 className="size-4 animate-spin" /> : <Check className="size-4" />} Salvar preferências</Button><p className="text-xs leading-5 text-muted-foreground">A ativação da execução automática dos avisos será concluída após a publicação da primeira versão do site.</p></CardContent></Card> : null}
      {section === "integrations" ? <Card className="border-border/80"><CardHeader><p className="section-kicker">Conectividade</p><CardTitle className="font-display text-2xl tracking-tight">Integrações</CardTitle><CardDescription>Registre os provedores homologados pela operação. As credenciais de cada serviço são inseridas de forma segura quando o conector for ativado.</CardDescription></CardHeader><CardContent><div className="space-y-3">{integrations.map((integration, index) => <div key={`${integration.name}-${index}`} className="grid gap-3 rounded-lg border p-4 md:grid-cols-[1fr_160px_auto_auto]"><Input value={integration.name} onChange={event => setIntegrations(current => current.map((item, position) => position === index ? { ...item, name: event.target.value } : item))} placeholder="Nome do provedor" /><select value={integration.category} onChange={event => setIntegrations(current => current.map((item, position) => position === index ? { ...item, category: event.target.value as typeof integration.category } : item))} className="h-10 rounded-md border bg-background px-3 text-sm"><option value="assinatura">Assinatura</option><option value="certidoes">Certidões</option><option value="conector">Conector</option></select><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={integration.enabled} onChange={event => setIntegrations(current => current.map((item, position) => position === index ? { ...item, enabled: event.target.checked } : item))} className="size-4 accent-black" /> Ativa</label><Button variant="ghost" size="sm" onClick={() => setIntegrations(current => current.filter((_item, position) => position !== index))}>Remover</Button></div>)}{!integrations.length ? <div className="rounded-lg border border-dashed p-6 text-sm text-muted-foreground">Nenhuma integração cadastrada. Adicione os provedores que sua operação pretende homologar.</div> : null}<div className="flex flex-wrap gap-2 pt-2"><Button variant="outline" onClick={() => setIntegrations(current => [...current, { name: "", category: "assinatura", enabled: false }])}><Plus className="size-4" /> Adicionar integração</Button><Button disabled={saveIntegrations.isPending || integrations.some(integration => !integration.name.trim())} onClick={() => saveIntegrations.mutate({ integrations })}>{saveIntegrations.isPending ? <Loader2 className="size-4 animate-spin" /> : <Check className="size-4" />} Salvar integrações</Button></div></div></CardContent></Card> : null}</section></div>
  </div></DashboardLayout>;
}
